import {GUIDES, FIELD_HELP} from './guide.js';
import {TYPES, weekStart, learnedThisMonth} from './model.js';

export const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const shortDate=value=>value?new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(value.length===10?value+'T12:00:00':value)):'Date not recorded';
const button=(action,label,extra='')=>`<button type="button" class="button small-button" data-action="${action}" ${extra}>${label}</button>`;
export const helpButton=key=>`<button type="button" class="help-button" data-help="${e(key)}" aria-label="Guide: ${e(GUIDES[key]?.title||key)}">? How to think about this</button>`;
export function inlineHelp(key){const h=FIELD_HELP[key];return h?`<details class="field-help"><summary>Help me think this through</summary><p>${e(h.meaning)}</p>${h.prompt?`<p><strong>Ask yourself:</strong> ${e(h.prompt)}</p>`:''}${h.example?`<p class="guide-example"><strong>Example:</strong> ${e(h.example)}</p>`:''}${h.pitfall?`<p><strong>Watch for:</strong> ${e(h.pitfall)}</p>`:''}</details>`:'';}
export function guideBody(key){const g=GUIDES[key]||GUIDES.home;return `<div class="guide-content"><p class="guide-intro">${e(g.intro)}</p><ol class="guide-steps">${g.steps.map(s=>`<li><h3>${e(s.title)}</h3><p>${e(s.body)}</p>${s.prompt?`<p class="guide-prompt">${e(s.prompt)}</p>`:''}${s.example?`<details><summary>See an example</summary><p class="guide-example">${e(s.example)}</p></details>`:''}</li>`).join('')}</ol><div class="guide-watch"><h3>Common traps</h3><ul>${g.pitfalls.map(p=>`<li>${e(p)}</li>`).join('')}</ul></div><p class="guide-done"><strong>You have enough to move forward when:</strong> ${e(g.doneWhen)}</p></div>`;}
export function guidePage(topic='home'){return `<div class="page-heading"><div><div class="eyebrow">THINK WITH YOUR WORKSPACE</div><h1>A guide to a growing research practice.</h1><p>Start with a question. Follow the reasoning. Use only the structure that helps.</p></div></div><div class="guide-layout"><nav class="guide-nav" aria-label="Guide topics">${Object.entries(GUIDES).map(([k,g])=>`<button type="button" data-guide-topic="${e(k)}" class="${k===topic?'active':''}" ${k===topic?'aria-current="page"':''}>${e(g.title)}</button>`).join('')}</nav><article class="surface"><h2 class="guide-title">${e((GUIDES[topic]||GUIDES.home).title)}</h2>${guideBody(topic)}<div class="guide-bottom">${Object.keys(TYPES).includes(topic)?`<button type="button" class="button primary" data-new-type="${e(topic)}">Create ${e(TYPES[topic].label.toLowerCase())}</button>`:button('new','Capture a thought')}</div></article></div>`;}
function smallEntry(n){return `<article class="focus-card"><div class="section-caption"><span class="type-label type-${e(n.type)}"><i class="type-dot"></i>${e(TYPES[n.type]?.label||n.type)}</span><span class="status ${e(n.status)}">${e(n.status)}</span></div><button type="button" class="focus-title" data-select="${e(n.id)}">${e(n.fields.question||n.title)}</button><p class="focus-context">${e(n.fields.explanation||n.body)}</p><div class="focus-uncertainty"><span class="field-caption">WHAT IS STILL OPEN?</span><p>${e(n.fields.uncertainty||'Record what you cannot yet distinguish.')}</p></div><div class="row-actions">${button('plan','Plan a test',`data-node="${e(n.id)}"`)}${button('decision','Record a change',`data-node="${e(n.id)}"`)}</div></article>`;}
export function planCard(p,data){const node=data.nodes.find(n=>n.id===p.nodeId);return `<article class="plan-card ${p.done?'is-done':''}"><div class="plan-heading"><label class="plan-check"><input type="checkbox" data-plan-done="${e(p.id)}" ${p.done?'checked':''} aria-label="Mark complete: ${e(p.action)}"><span>${e(p.action)}</span></label><button type="button" class="text-button small" data-edit-plan="${e(p.id)}">Edit</button></div>${node?`<button type="button" class="inline-link small" data-select="${e(node.id)}">${e(node.title)} ↗</button>`:''}<p><strong>Why this step:</strong> ${e(p.why||'Add the uncertainty this action will reduce.')}</p>${p.outcome?`<p><strong>Outcome:</strong> ${e(p.outcome)}</p>`:''}</article>`;}
export function decisionCard(d,data){return `<article class="judgment-card"><div class="entry-date">${shortDate(d.createdAt)}${d.outcome?` · ${e(({proceed:'Try now',evidence:'Gather evidence',pause:'Pause',drop:'Let go'})[d.outcome]||d.outcome)}`:''}</div><h3>${e(d.title)}</h3>${d.before?`<p><strong>Before:</strong> ${e(d.before)}</p>`:''}${d.trigger?`<p><strong>New evidence or feedback:</strong> ${e(d.trigger)}</p>`:''}${d.after?`<p><strong>Now:</strong> ${e(d.after)}</p>`:''}<p class="prose">${e(d.body)}</p>${d.action?`<p><strong>Next:</strong> ${e(d.action)}</p>`:''}${d.nodeId?`<button type="button" class="inline-link small" data-select="${e(d.nodeId)}">${e(data.nodes.find(n=>n.id===d.nodeId)?.title||'Related element')} ↗</button>`:''}<div class="entry-actions"><button type="button" class="text-button small" data-edit-entry="${e(d.id)}" data-kind="decision">Edit</button></div></article>`;}
export function deskPage(data,week){const focus=data.nodes.filter(n=>data.focusIds.includes(n.id));const plans=data.plans.filter(p=>p.week===week&&!p.done);const decisions=[...data.decisions].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,3);return `<div class="page-heading"><div><div class="eyebrow">RETURN TO THE QUESTION</div><h1>Pick up the thread.</h1><p>What is still unresolved—and what would make the next step worth taking?</p></div>${helpButton('home')}</div><div class="section-heading"><div><h2>Your current focus</h2><p>Choose the questions you want to return to. Active does not automatically mean urgent.</p></div>${button('focus','Choose focus')}</div>${focus.length?`<div class="focus-grid">${focus.map(smallEntry).join('')}</div>`:`<div class="surface desk-empty"><h2>Choose one question to begin with.</h2><p>Bring a problem or project onto your desk. You can leave the rest in your atlas.</p><div class="row-actions">${button('focus','Choose from my atlas')}<button type="button" class="button primary" data-new-type="problem">Capture a question</button></div></div>`}<div class="desk-columns"><section><div class="section-heading"><div><h2>The next informative steps</h2><p>Week of ${shortDate(week)} · selected by you</p></div>${button('plan','＋ Plan a step')}</div>${plans.length?plans.map(p=>planCard(p,data)).join(''):'<p class="surface muted small">No steps chosen for this week. A reading, a simulation, or a conversation can be enough.</p>'}</section><section><div class="section-heading"><h2>What changed your mind?</h2>${button('decision','＋ Record')}</div>${decisions.length?decisions.map(d=>decisionCard(d,data)).join(''):'<p class="surface muted small">Save a judgment, the evidence behind it, and what you will do differently.</p>'}</section></div><section class="start-guide-strip"><div><h3>Building your first research map?</h3><p>Read a source → recover its question → identify a bottleneck → connect a capability → choose a small test.</p></div><button type="button" class="button" data-help="paper">Walk through a reading</button></section>`;}
export function weeklyPage(data,week){const plans=data.plans.filter(p=>p.week===week);const parked=data.nodes.filter(n=>n.status==='paused');return `<div class="page-heading"><div><div class="eyebrow">PLAN TO LEARN SOMETHING</div><h1>A week with a reason.</h1><p>Choose a few actions that reduce uncertainty. Keep the rest available for later.</p></div>${helpButton('week')}</div><div class="week-toolbar"><button type="button" class="button" data-action="previous-week" aria-label="Previous week">←</button><label>Week of <input type="date" id="week-picker" value="${e(week)}" aria-label="Week starting"></label><button type="button" class="button" data-action="next-week" aria-label="Next week">→</button>${button('current-week','This week')}<span class="spacer"></span>${button('agenda','Export agenda ↗')}<button type="button" class="button primary" data-action="plan">＋ Plan a step</button></div><div class="two-col"><section><div class="section-heading"><h2>Chosen for this week</h2><span class="small muted">${plans.filter(p=>p.done).length} of ${plans.length} completed</span></div>${plans.length?plans.map(p=>planCard(p,data)).join(''):'<div class="surface desk-empty"><h2>Start with a useful uncertainty.</h2><p>Which small action would help you decide what to do next? Your active projects are not added automatically.</p><button type="button" class="button" data-action="plan">Plan one step</button></div>'}</section><aside class="surface"><h2>Before adding a task</h2><ol class="weekly-prompts"><li>What are you trying to find out?</li><li>Why is this the smallest useful next step?</li><li>What would you do after each possible outcome?</li><li>Does it fit your actual time and energy this week?</li></ol><p class="small muted">Completed records stay with their original week. Move unfinished work deliberately by editing its date.</p>${helpButton('week')}</aside></div><div class="section-heading"><div><h2>Waiting for a better moment</h2><p>Revisit conditions keep worthwhile ideas from disappearing.</p></div></div><div class="idea-grid">${parked.map(n=>`<article class="idea-card"><span class="type-label">${e(TYPES[n.type].label)}</span><h2>${e(n.title)}</h2><span class="field-caption">REVISIT WHEN</span><p>${e(n.fields.restart||'Record the change that would make this worth returning to.')}</p><div class="card-actions">${button('decision','Reconsider',`data-node="${e(n.id)}"`)}</div></article>`).join('')||'<p class="muted small">Paused elements will appear here with their restart conditions.</p>'}</div>`;}
export function unifiedJournal(data){return [
  ...data.nodes.filter(n=>n.type==='reflection').map(n=>({...n,entryKind:'reflection',entryDate:n.eventDate||n.createdAt})),
  ...data.reviews.map(r=>({...r,entryKind:'review',entryDate:r.createdAt})),
  ...data.decisions.map(d=>({...d,entryKind:'decision',entryDate:d.createdAt}))
].sort((a,b)=>new Date(b.entryDate.length===10?b.entryDate+'T12:00:00':b.entryDate).getTime()-new Date(a.entryDate.length===10?a.entryDate+'T12:00:00':a.entryDate).getTime());}
export function journalPage(data,period,kind='all'){
  const knowledge=learnedThisMonth(data,period),unknown=data.nodes.filter(n=>['paper','capability','resource'].includes(n.type)&&!n.learnedOn).length;
  const problems=data.nodes.filter(n=>n.type==='problem'&&n.status!=='archived');
  const entries=unifiedJournal(data).filter(x=>kind==='all'||x.entryKind===kind);
  return `<div class="page-heading"><div><div class="eyebrow">PRESERVE HOW YOU THINK</div><h1>Notice what is becoming possible.</h1><p>Your reflection notes, monthly reviews, and research decisions share one history.</p></div>${helpButton('review')}</div><div class="two-col"><div><section class="reflection-intro"><h2>Old questions × new knowledge</h2><p>Choose an old question and something actually learned in the month—not simply imported then.</p><label class="month-picker">Learning month <input type="month" id="learning-month" value="${e(period)}"></label></section><div class="review-grid"><label class="form-field"><span>A question to revisit</span><select id="review-question"><option value="">Choose a question</option>${problems.map(n=>`<option value="${e(n.id)}">${e(n.title)}</option>`).join('')}</select></label><label class="form-field"><span>Learned during this month</span><select id="review-knowledge"><option value="">Choose a source or capability</option>${knowledge.map(n=>`<option value="${e(n.id)}">${e(n.title)}</option>`).join('')}</select></label></div><p class="small muted" style="margin-top:12px">${knowledge.length} dated learning records · ${unknown} have no learning date and are excluded.</p><div class="row-actions" style="margin-top:15px">${button('connect-review','Explain a possible connection')}${button('review','Write a monthly review')}</div><div class="section-heading"><h2>Your thinking history</h2><select id="journal-kind" class="period-select" aria-label="Filter thinking history">${[['all','All records'],['reflection','Reflection notes'],['review','Monthly reviews'],['decision','Decisions']].map(([v,l])=>`<option value="${v}" ${v===kind?'selected':''}>${l}</option>`).join('')}</select></div>${entries.length?`<div class="timeline">${entries.map(r=>`<article class="timeline-entry"><div class="entry-date">${shortDate(r.entryDate)} · ${r.entryKind==='review'?'Monthly review':r.entryKind==='reflection'?'Reflection note':'Research decision'}${r.period?` · ${e(r.period)}`:''}</div><h3>${e(r.title)}</h3>${r.before?`<p class="entry-body"><strong>Before:</strong> ${e(r.before)}</p>`:''}${r.trigger?`<p class="entry-body"><strong>Changed by:</strong> ${e(r.trigger)}</p>`:''}${r.after?`<p class="entry-body"><strong>Now:</strong> ${e(r.after)}</p>`:''}<p class="entry-body">${e(r.body)}</p>${r.action?`<p class="entry-body"><strong>Next:</strong> ${e(r.action)}</p>`:''}<div class="entry-actions">${r.entryKind==='reflection'?`<button type="button" class="text-button" data-edit="${e(r.id)}">Edit reflection</button><button type="button" class="text-button" data-select="${e(r.id)}">View connections</button>`:`<button type="button" class="text-button" data-edit-entry="${e(r.id)}" data-kind="${r.entryKind}">Edit</button><button type="button" class="text-button" data-delete-entry="${e(r.id)}" data-kind="${r.entryKind}">Delete</button>`}${r.nodeId?`<button type="button" class="text-button" data-select="${e(r.nodeId)}">Related research</button>`:''}</div></article>`).join('')}</div>`:'<p class="surface muted small">Capture a reflection or record a decision. Both will appear here.</p>'}</div><aside class="surface"><h2>Trace a change in judgment</h2><ol class="weekly-prompts"><li>What did you previously believe?</li><li>What observation, feedback, or contradiction changed the picture?</li><li>What do you now think—and what remains uncertain?</li><li>What will you do differently?</li></ol><div class="row-actions"><button type="button" class="button" data-new-type="reflection">Quick reflection</button>${button('decision','Structured change')}${button('journal','Export journal ↗')}</div>${helpButton('reflection')}</aside></div>`;
}
